package com.yonlab.vision;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;
public final class OneRootContractsTest {
 @Test public void documentModelDefaultsFollowSelectedRegion(){assertEquals("mlkit-ocr-latin",OneModelPolicy.defaultId("ocr",27,"GO"));assertEquals("mlkit-ocr-ko",OneModelPolicy.defaultId("ocr",27,"KO"));assertEquals("mlkit-ocr-ko",OneModelPolicy.defaultId("ocr",27,"ALL"));assertEquals("efficientdet-lite0",OneModelPolicy.defaultId("detect",27,"GO"));assertEquals("mobilenet-v4-fp32",OneModelPolicy.defaultId("classify",27,"ALL"));assertEquals("ssd-mobilenet-v1",OneModelPolicy.defaultId("flow",27,"KO"));}
 @Test public void recentHistoryRetainsNewRunsAcrossRotation()throws Exception{StringBuilder source=new StringBuilder();for(int i=0;i<1105;i++)source.append(i).append('\n');List<String> tail=RecentRunLines.tail(new BufferedReader(new StringReader(source.toString())),1000);assertEquals(1000,tail.size());assertEquals("105",tail.get(0));assertEquals("1104",tail.get(999));assertEquals("905",tail.subList(800,1000).get(0));}
 @Test public void capturedPlaylistPhotoNeedsStableSnapshot(){assertTrue(OneImportPolicy.snapshot("com.yonlab.one.files","com.yonlab.one","/photos/capture.jpg","image/jpeg"));assertFalse(OneImportPolicy.snapshot("com.yonlab.one.files","com.yonlab.one","/demos/v1/example.jpg","image/jpeg"));assertFalse(OneImportPolicy.direct("content","audio/wav",true));assertTrue(OneImportPolicy.direct("content","video/mp4",true));}
 @Test public void visibleFaceDetailsShowRealAttributesAndOmitMissingValues(){Observations.Face f=new Observations.Face();f.expressionIndex=3;f.expressionConfidence=.8f;f.ageYears=32;f.yaw=12;f.leftEye=.9f;f.mouthOpen=.2f;String actual=OneFacePresentation.details(Collections.singletonList(f));for(String word:new String[]{"행복","32세","고개 좌우","왼쪽 눈","입 벌림"})assertTrue(word,actual.contains(word));String missing=OneFacePresentation.details(Collections.singletonList(new Observations.Face()));assertFalse(missing.contains("NaN"));assertFalse(missing.contains("0세"));}
}
